mapper.select:
select c.id as customerId, c.name as customerName, c.mobile, su.name as ownerName, sd.name as departmentName, cf.field_value as customerSource, c.collection_time as eventTime from customer c left join sys_user su on su.id = c.owner left join sys_organization_user sou on sou.organization_id = #{orgId} and sou.user_id = c.owner left join sys_department sd on sd.id = sou.department_id left join customer_field cf on cf.resource_id = c.id and cf.field_id = ( select mf.id from sys_module_field mf join sys_module_form form on mf.form_id = form.id where form.organization_id = #{orgId} and form.form_key = 'customer' and mf.internal_key = 'customerSource' limit 1 ) where c.in_shared_pool is false and c.collection_time between #{request.startTime} and #{request.endTime}
and c.owner = #{request.dimensionKey}
and sou.department_id = #{request.dimensionKey}
and ifnull(cf.field_value, '') = #{request.dimensionKey}
and date_format(from_unixtime(c.collection_time / 1000), '%Y-%m-%d') = #{request.dimensionKey}
and date_format(from_unixtime(c.collection_time / 1000), '%Y-%m') = #{request.dimensionKey}
order by c.collection_time desc, c.id desc

select c.id as customerId, c.name as customerName, c.mobile, owner_user.name as ownerName, owner_dept.name as departmentName, cf.field_value as customerSource, max(f.follow_time) as eventTime from follow_up_record f join customer c on c.id = f.customer_id left join sys_user owner_user on owner_user.id = c.owner left join sys_organization_user owner_sou on owner_sou.organization_id = #{orgId} and owner_sou.user_id = c.owner left join sys_department owner_dept on owner_dept.id = owner_sou.department_id left join customer_field cf on cf.resource_id = c.id and cf.field_id = ( select mf.id from sys_module_field mf join sys_module_form form on mf.form_id = form.id where form.organization_id = #{orgId} and form.form_key = 'customer' and mf.internal_key = 'customerSource' limit 1 ) left join sys_organization_user action_sou on action_sou.organization_id = #{orgId} and action_sou.user_id = f.owner where c.in_shared_pool is false and f.follow_time between #{request.startTime} and #{request.endTime}
and f.owner = #{request.dimensionKey}
and action_sou.department_id = #{request.dimensionKey}
and ifnull(cf.field_value, '') = #{request.dimensionKey}
and date_format(from_unixtime(f.follow_time / 1000), '%Y-%m-%d') = #{request.dimensionKey}
and date_format(from_unixtime(f.follow_time / 1000), '%Y-%m') = #{request.dimensionKey}
group by c.id, c.name, c.mobile, owner_user.name, owner_dept.name, cf.field_value order by max(f.follow_time) desc, c.id desc

select current_audit.es_id as auditId, latest.customerId, latest.customerName, latest.mobile, latest.ownerName, latest.departmentName, latest.customerSource, current_audit.friend_phone as friendPhone, current_audit.contact_im_app_nick_name as contactImAppNickName, current_audit.contact_im_app_account as contactImAppAccount, current_audit.contact_im_app_note as contactImAppNote, current_audit.staff_name as staffName, current_audit.`timestamp` as eventTime from ( select date_format(from_unixtime(a.`timestamp` / 1000), '%Y-%m-%d') as statDate, c.id as customerId, c.name as customerName, c.mobile, owner_user.name as ownerName, owner_dept.name as departmentName, cf.field_value as customerSource, su.id as operatorUserId, max(a.`timestamp`) as latestTimestamp from mmba_wx_friend_change_audit a join sys_user su on su.um = a.um join customer c on c.mobile = a.friend_phone and c.owner = su.id and c.in_shared_pool is false left join sys_user owner_user on owner_user.id = c.owner left join sys_organization_user owner_sou on owner_sou.organization_id = #{orgId} and owner_sou.user_id = c.owner left join sys_department owner_dept on owner_dept.id = owner_sou.department_id left join customer_field cf on cf.resource_id = c.id and cf.field_id = ( select mf.id from sys_module_field mf join sys_module_form form on mf.form_id = form.id where form.organization_id = #{orgId} and form.form_key = 'customer' and mf.internal_key = 'customerSource' limit 1 ) left join sys_organization_user action_sou on action_sou.organization_id = #{orgId} and action_sou.user_id = su.id where a.is_friend = '1' and a.`timestamp` between #{request.startTime} and #{request.endTime} and a.friend_phone is not null and a.friend_phone != ''
and su.id = #{request.dimensionKey}
and action_sou.department_id = #{request.dimensionKey}
and ifnull(cf.field_value, '') = #{request.dimensionKey}
and date_format(from_unixtime(a.`timestamp` / 1000), '%Y-%m-%d') = #{request.dimensionKey}
and date_format(from_unixtime(a.`timestamp` / 1000), '%Y-%m') = #{request.dimensionKey}
group by date_format(from_unixtime(a.`timestamp` / 1000), '%Y-%m-%d'), c.id, c.name, c.mobile, owner_user.name, owner_dept.name, cf.field_value, su.id ) latest join sys_user operator_user on operator_user.id = latest.operatorUserId join mmba_wx_friend_change_audit current_audit on current_audit.um = operator_user.um and current_audit.friend_phone = latest.mobile and current_audit.`timestamp` = latest.latestTimestamp and current_audit.is_friend = '1' order by current_audit.`timestamp` desc, current_audit.es_id desc

select cra.es_id as auditId, c.id as customerId, c.name as customerName, c.mobile, owner_user.name as ownerName, owner_dept.name as departmentName, cf.field_value as customerSource, cra.staff_name as staffName, cra.begin_timestamp as eventTime, cra.begin_time as beginTime, cra.end_time as endTime, cra.duration, cra.is_connected as isConnected, cra.direction from mmba_call_record_audit cra join sys_user su on su.um = cra.um join customer c on c.mobile = cra.customer_tel and c.owner = su.id and c.in_shared_pool is false left join sys_user owner_user on owner_user.id = c.owner left join sys_organization_user owner_sou on owner_sou.organization_id = #{orgId} and owner_sou.user_id = c.owner left join sys_department owner_dept on owner_dept.id = owner_sou.department_id left join customer_field cf on cf.resource_id = c.id and cf.field_id = ( select mf.id from sys_module_field mf join sys_module_form form on mf.form_id = form.id where form.organization_id = #{orgId} and form.form_key = 'customer' and mf.internal_key = 'customerSource' limit 1 ) left join sys_organization_user action_sou on action_sou.organization_id = #{orgId} and action_sou.user_id = su.id where cra.begin_timestamp between #{request.startTime} and #{request.endTime} and cra.direction = 0 and cra.customer_tel is not null and cra.customer_tel != ''
and ifnull(cra.is_connected, 0) = 1
and ifnull(cra.is_connected, 0) = 1 and ifnull(cra.duration, 0) >= 60
and ifnull(cra.is_connected, 0) = 1 and ifnull(cra.duration, 0) >= 180
and su.id = #{request.dimensionKey}
and action_sou.department_id = #{request.dimensionKey}
and ifnull(cf.field_value, '') = #{request.dimensionKey}
and date_format(from_unixtime(cra.begin_timestamp / 1000), '%Y-%m-%d') = #{request.dimensionKey}
and date_format(from_unixtime(cra.begin_timestamp / 1000), '%Y-%m') = #{request.dimensionKey}
order by cra.begin_timestamp desc, cra.es_id desc
